style.css:
@-moz-document domain("pomofocus.io") {
/* Fondo de la página */
  body {
    background-color: #ffe6f2 !important;
    color: #5a5a5a !important;
  }

  /* Contenedor principal */
  .container {
    background-color: #ffccdd !important;
  }

  /* Temporizador */
  .timer {
    background-color: #ff99c2 !important;
    color: #fff !important;
  }

  /* Botones */
  .btn,
  .btn:hover {
    background-color: #ff6699 !important;
    color: #fff !important;
  }

  /* Bordes y sombras */
  .container,
  .timer,
  .btn {
    border-color: #ff99c2 !important;
    box-shadow: 0px 4px 8px rgba(255, 102, 153, 0.3) !important;
  }

  /* Texto */
  h1, h2, h3, h4, p {
    color: #cc0066 !important;
  }
}
